"""Derive main-text versions of tables generated for the supplement.
Numbers are copied verbatim from the generated files; only headers and column specs change."""
import re, pathlib
T = pathlib.Path(__file__).resolve().parent.parent / 'tables'

def derive(src, dst, reps):
    s = (T / src).read_text()
    for o, n in reps:
        assert s.count(o) == 1, (src, o)
        s = s.replace(o, n)
    hdr = '%% derived by scripts/make_main_moved.py from tables/%s -- do not edit by hand\n' % src
    (T / dst).write_text(hdr + s)

# tab_sign.tex is now generated by scripts/make_s24.py (replay of the released check, 33-24)
derive('supp_s23_wbps.tex', 'tab_wbps.tex', [
    (r'Confidence & AP & First correct (\%) & Precision at 3 (\%) & AP & First correct (\%) \\',
     r'Confidence & AP & First & P@3 & AP & First \\'),
    (r'& \multicolumn{3}{c}{CNOS masks (W0)} & \multicolumn{2}{c}{CNOS and NOCTIS masks (W1)}',
     r'& \multicolumn{3}{c}{W0: CNOS masks} & \multicolumn{2}{c}{W1: CNOS + NOCTIS}'),
])
print('ok')
